// C14
import olympiad;
size(7cm);

real x = 50; real y = 20;

pair q = (1, 0);
pair r = (0, 0);
pair p = intersectionpoints((10 * dir(x))--r, q--(shift(q) * 10 * dir(180 - x)))[0];
