label("$Q$", q, SE);
label("$S$", s, N);
label("$P$", p, NW);

// Label angles
label("$x^\circ$", q, 2 * W + 2 * NW);
label("$x^\circ$", q, 4 * N + 2 * NW);
label("$2y^\circ$", s, 5 * S + 4 * SW);
label("$3y^\circ$", p, 4 * S);

// Tick marks
